import heapq

def match(orders):
    buy_heap = []   # max-heap by price: stored as (-price, index, id)
    sell_heap = []  # min-heap by price: stored as (price, index, id)
    book = {}       # id -> dict with side, price, qty, index, active
    trades = []
    counter = 0

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['active']:
                book[oid]['active'] = False
            continue

        oid = order[1]
        side = order[2]

        if typ == 'market':
            qty = order[3]
            price = None
        else:
            price = order[3]
            qty = order[4]

        index = counter
        counter += 1

        remaining = qty

        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            _, opp_index, opp_id = top

            if opp_id not in book or not book[opp_id]['active'] or book[opp_id]['qty'] <= 0:
                heapq.heappop(opp_heap)
                continue

            actual_price = book[opp_id]['price']

            if typ != 'market':
                if side == 'buy' and actual_price > price:
                    break
                if side == 'sell' and actual_price < price:
                    break

            trade_qty = min(remaining, book[opp_id]['qty'])

            if side == 'buy':
                trades.append([oid, opp_id, actual_price, trade_qty])
            else:
                trades.append([opp_id, oid, actual_price, trade_qty])

            remaining -= trade_qty
            book[opp_id]['qty'] -= trade_qty

            if book[opp_id]['qty'] == 0:
                book[opp_id]['active'] = False
                heapq.heappop(opp_heap)
            # else partial fill, stays at top of heap since price/index unchanged

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'index': index, 'active': True}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, index, oid))
            else:
                heapq.heappush(sell_heap, (price, index, oid))
        # ioc/market remainder discarded; fully-filled limit order not added to book

    return trades

